{
  "hooks": {
    "PreToolUse": [
      {
        "matcher": "Write|Edit|NotebookEdit",
        "hooks": [
          {
            "type": "command",
            "command": "branch=$(git branch --show-current 2>/dev/null); if [ \"$branch\" = 'develop' ] || [ \"$branch\" = 'main' ]; then echo \"BLOCKED: You are on branch '$branch'. Claude Code must not make file changes on develop or main. Switch to a feature branch first.\"; exit 1; fi"
          },
          {
            "type": "command",
            "command": "[ -f .claude/hooks/tier2Warn.sh ] && bash .claude/hooks/tier2Warn.sh || true"
          }
        ]
      }
    ],
    "PostToolUse": [
      {
        "matcher": "Write",
        "hooks": [
          {
            "type": "command",
            "command": "root=$(git rev-parse --show-toplevel 2>/dev/null) && f=$(jq -r '.tool_input.file_path') && \"$root/node_modules/.bin/prettier\" --write \"$f\" 2>&1 || true",
            "statusMessage": "Formatting new file with Prettier..."
          }
        ]
      },
      {
        "matcher": "Edit|Write",
        "hooks": [
